// (kit/blocks/accounts/LogIn.html; source 56c114a887fa), with the vocabulary in
// functional/blocks/spec.json. Do not edit: change the spec (or the App Block) and generate again.
//
// Steps (e2e):
//   Given I am on the log in page
//   When I log in as {email} with {password}
//   When I enter the email {email}
//   When I enter the password {password}
//   When I press Log In
//   When I untick keep me logged in
//   When I follow the forgot password link
//   When I follow the sign up link
//   Then I see the log in error
//   Then the email field has {email}
//   Then keep me logged in is ticked
//   Then the log in form is in the {state} state
// States (from the card): Empty, Field error, Sending, Wrong email or password, Too many tries, Offline, Success.
// Checked by the state step: Empty, Field error, Sending, Wrong email or password, Too many tries, Offline.
import { Registry } from '../../js/registry.js';
import * as p from '../../js/primitives.js';

export const BLOCK = 'LogIn';
export const ROUTE = '/login';
export const STATES = ["Empty", "Field error", "Sending", "Wrong email or password", "Too many tries", "Offline", "Success"];
export const DEFAULT_STATE = 'Empty';
export const CHECKED_STATES = ["Empty", "Field error", "Sending", "Wrong email or password", "Too many tries", "Offline"];
export const DEMO = ["kit/blocks/accounts/LogIn.html"];
export const SELF_TEST = [
  "Given I am on the log in page",
  "Then the log in form is in the \"Empty\" state",
  "Then keep me logged in is ticked",
  "When I enter the email \"aiko@example.com\"",
  "Then the email field has \"aiko@example.com\"",
  "When I untick keep me logged in",
  "When I follow the sign up link",
  "Then the log in form is in the \"Empty\" state",
];

export const steps = new Registry({ block: BLOCK });

/** The LogIn block on a page: its controls, found as a person finds them (role and name, label, text). */
export class LogIn {
  constructor(page, baseURL = '') {
    this.page = page;
    this.baseURL = baseURL;
  }

  async form() {
    return p.control(this.page, { css: '#login-form', block: BLOCK });
  }

  async email() {
    return p.control(await this.form(), { label: 'Email', block: BLOCK });
  }

  async password() {
    return p.control(await this.form(), { label: 'Password', block: BLOCK });
  }

  async remember() {
    return p.control(await this.form(), { role: 'checkbox', name: 'Keep me logged in', block: BLOCK });
  }

  async submit() {
    return p.control(await this.form(), { role: 'button', name: 'Log In', block: BLOCK });
  }

  async forgot() {
    return p.control(await this.form(), { role: 'link', name: 'Forgot your password?', block: BLOCK });
  }

  async signup() {
    return p.control(await this.form(), { role: 'link', name: 'Sign Up', block: BLOCK });
  }

  async error() {
    return p.control(await this.form(), { css: '#login-error', block: BLOCK });
  }

  async invalid() {
    return p.control(await this.form(), { css: '[aria-invalid="true"]', block: BLOCK });
  }

  /** Check one of the card's states: Empty, Field error, Sending, Wrong email or password, Too many tries, Offline. */
  async expectState(state) {
    const b = this;
    if (state === 'Empty') {
      await p.expectValue(await b.email(), '');
      await p.expectValue(await b.password(), '');
      await p.expectHidden(await b.error());
    } else if (state === 'Field error') {
      await p.expectVisible((await b.invalid()).first());
    } else if (state === 'Sending') {
      await p.expectAttribute(await b.submit(), 'aria-busy', 'true');
    } else if (state === 'Wrong email or password') {
      await p.expectVisible(await b.error());
    } else if (state === 'Too many tries') {
      await p.expectText(await b.error(), 'Too many tries');
    } else if (state === 'Offline') {
      await p.expectText(await b.error(), 'offline');
    } else {
      throw new Error(`LogIn has no check for the state '${state}'; checked: ${CHECKED_STATES.join(', ')}`);
    }
  }
}

steps.step("Given I am on the log in page", async (world, _values) => {
  const b = new LogIn(world.page, world.baseURL ?? '');
  await p.goto(world.page, `${b.baseURL}${ROUTE}`);
  await p.expectVisible(await b.submit());
}, { level: 'e2e' });

steps.step("When I log in as {email} with {password}", async (world, { email, password }) => {
  const b = new LogIn(world.page, world.baseURL ?? '');
  await p.fill(await b.email(), String(email));
  await p.fill(await b.password(), String(password));
  await p.click(await b.submit());
}, { level: 'e2e' });

